//! Process confinement for `graft run` (ADR 0014).
//!
//! A [`Policy`] lists the directories a confined process may write to; it
//! may read anything. On Linux the policy is enforced with Landlock by
//! [`confine_self`], which `graft` calls in a helper process just before it
//! `exec`s the command. On macOS `seatbelt_command` (macOS only) wraps the command in
//! `sandbox-exec` with a profile generated by `seatbelt_profile`.
//!
//! [`IgnoreInterrupts`] keeps `graft run` alive while the command it
//! started handles Ctrl-C itself.
//!
//! It is one of the two crates allowed to contain `unsafe` (AGENTS.md §6).
//! `unsafe` is denied at the crate root and allowed only in the `signals`
//! module, each block with a `SAFETY` comment.

#![deny(unsafe_code)]

mod signals;

pub use signals::IgnoreInterrupts;

use std::path::{Path, PathBuf};

/// Device files every process may write to, whatever the policy.
#[cfg_attr(not(any(target_os = "linux", test)), allow(dead_code))]
const DEVICE_FILES: &[&str] = &[
    "/dev/null",
    "/dev/zero",
    "/dev/full",
    "/dev/tty",
    "/dev/ptmx",
];

/// Errors from building or applying a policy.
#[derive(Debug, thiserror::Error)]
#[non_exhaustive]
pub enum SandboxError {
    /// A writable path could not be resolved.
    #[error("sandbox path {}: {source}", path.display())]
    Path {
        /// The path as given.
        path: PathBuf,
        /// Why it could not be resolved.
        #[source]
        source: std::io::Error,
    },
    /// A writable path is not absolute.
    #[error("sandbox path {} must be absolute", path.display())]
    Relative {
        /// The path as given.
        path: PathBuf,
    },
    /// The kernel enforces no Landlock restriction.
    #[error(
        "this kernel does not enforce Landlock, so `graft run` cannot confine the command; \
         it needs Linux 5.13 or later with Landlock enabled (`landlock` in /sys/kernel/security/lsm, \
         or `lsm=landlock,...` on the kernel command line)"
    )]
    Unsupported,
    /// Landlock refused the policy.
    #[error("applying the Landlock policy: {0}")]
    Landlock(String),
    /// This platform has no confinement mechanism.
    #[error("graft run cannot confine commands on this platform")]
    Platform,
}

/// Result alias using [`SandboxError`].
pub type Result<T, E = SandboxError> = std::result::Result<T, E>;

/// What a confined process may write to.
#[derive(Debug, Clone, PartialEq, Eq)]
pub struct Policy {
    writable: Vec<PathBuf>,
}

impl Policy {
    /// A policy allowing writes below each of `paths` (directories or
    /// files), which must exist. Each is canonicalised, so the policy names
    /// what the kernel will check.
    ///
    /// # Errors
    ///
    /// [`SandboxError::Relative`] or [`SandboxError::Path`].
    pub fn new<P: AsRef<Path>>(paths: impl IntoIterator<Item = P>) -> Result<Self> {
        let mut writable = Vec::new();
        for p in paths {
            let p = p.as_ref();
            if !p.is_absolute() {
                return Err(SandboxError::Relative { path: p.to_owned() });
            }
            let canonical = p.canonicalize().map_err(|source| SandboxError::Path {
                path: p.to_owned(),
                source,
            })?;
            if !writable.contains(&canonical) {
                writable.push(canonical);
            }
        }
        Ok(Self { writable })
    }

    /// The canonical writable paths, in the order given.
    #[must_use]
    pub fn writable(&self) -> &[PathBuf] {
        &self.writable
    }
}

/// How well [`confine_self`] could enforce the policy.
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Enforcement {
    /// Every write right is restricted.
    Full,
    /// The kernel's Landlock ABI is older than this build knows, so some
    /// rights (renames across directories, truncation) are not restricted.
    Partial,
}

/// Which mechanism this platform would use, and whether it looks usable.
/// For `graft doctor`; [`confine_self`] reports the definitive answer.
pub fn mechanism() -> (&'static str, Result<(), String>) {
    #[cfg(target_os = "linux")]
    {
        let lsm = std::fs::read_to_string("/sys/kernel/security/lsm");
        let ok = match lsm {
            Ok(list) if list.trim().split(',').any(|m| m == "landlock") => Ok(()),
            Ok(list) => Err(format!(
                "landlock is not in the active LSMs ({})",
                list.trim()
            )),
            Err(e) => Err(format!("cannot read /sys/kernel/security/lsm: {e}")),
        };
        ("landlock", ok)
    }
    #[cfg(target_os = "macos")]
    {
        let ok = if Path::new(SANDBOX_EXEC).is_file() {
            Ok(())
        } else {
            Err(format!("{SANDBOX_EXEC} is missing"))
        };
        ("seatbelt", ok)
    }
    #[cfg(not(any(target_os = "linux", target_os = "macos")))]
    {
        ("none", Err("unsupported platform".to_owned()))
    }
}

/// Restricts the current process (and every process it starts) to the
/// policy, with the best Landlock ABI the kernel has. Call it in a
/// single-threaded process right before `exec`.
///
/// # Errors
///
/// [`SandboxError::Unsupported`] if the kernel enforces nothing, and
/// [`SandboxError::Landlock`] or [`SandboxError::Path`] if the policy
/// cannot be applied.
#[cfg(target_os = "linux")]
pub fn confine_self(policy: &Policy) -> Result<Enforcement> {
    use landlock::{
        ABI, AccessFs, PathBeneath, PathFd, Ruleset, RulesetAttr, RulesetCreatedAttr, RulesetStatus,
    };
    let abi = ABI::V6;
    let write = AccessFs::from_write(abi);
    let file_write = write & AccessFs::from_file(abi);
    let mut targets: Vec<(&Path, _)> = policy
        .writable()
        .iter()
        .map(|p| (p.as_path(), if p.is_dir() { write } else { file_write }))
        .collect();
    for dev in DEVICE_FILES.iter().map(Path::new).filter(|d| d.exists()) {
        targets.push((dev, file_write));
    }
    if Path::new("/dev/pts").is_dir() {
        targets.push((Path::new("/dev/pts"), file_write));
    }
    let mut rules = Vec::new();
    for (path, access) in targets {
        let fd = PathFd::new(path)
            .map_err(|e| SandboxError::Landlock(format!("{}: {e}", path.display())))?;
        rules.push(Ok::<_, landlock::RulesetError>(PathBeneath::new(
            fd, access,
        )));
    }
    let ll = |e: landlock::RulesetError| SandboxError::Landlock(e.to_string());
    let ruleset = Ruleset::default()
        .handle_access(write)
        .map_err(ll)?
        .create()
        .map_err(ll)?
        .add_rules(rules)
        .map_err(ll)?;
    let status = ruleset.restrict_self().map_err(ll)?;
    match status.ruleset {
        RulesetStatus::FullyEnforced => Ok(Enforcement::Full),
        RulesetStatus::PartiallyEnforced => Ok(Enforcement::Partial),
        RulesetStatus::NotEnforced => Err(SandboxError::Unsupported),
    }
}

/// `confine_self` exists only on Linux.
///
/// # Errors
///
/// Always [`SandboxError::Platform`].
#[cfg(not(target_os = "linux"))]
pub fn confine_self(_policy: &Policy) -> Result<Enforcement> {
    Err(SandboxError::Platform)
}

/// The macOS sandbox launcher.
#[cfg(any(target_os = "macos", test))]
pub const SANDBOX_EXEC: &str = "/usr/bin/sandbox-exec";

/// A Seatbelt string literal.
#[cfg(any(target_os = "macos", test))]
fn sbpl_string(path: &Path) -> String {
    let mut s = String::from("\"");
    for c in path.to_string_lossy().chars() {
        if matches!(c, '"' | '\\') {
            s.push('\\');
        }
        s.push(c);
    }
    s.push('"');
    s
}

/// The Seatbelt profile for `policy`: anything is allowed except writing
/// to files outside the writable paths and the terminal devices.
#[cfg(any(target_os = "macos", test))]
#[must_use]
pub fn seatbelt_profile(policy: &Policy) -> String {
    use std::fmt::Write as _;
    let mut p =
        String::from("(version 1)\n(allow default)\n(deny file-write*)\n(allow file-write*\n");
    for w in policy.writable() {
        let kind = if w.is_dir() { "subpath" } else { "literal" };
        let _ = writeln!(p, "  ({kind} {})", sbpl_string(w));
    }
    for dev in ["/dev/null", "/dev/zero", "/dev/tty", "/dev/dtracehelper"] {
        let _ = writeln!(p, "  (literal \"{dev}\")");
    }
    p.push_str("  (regex #\"^/dev/ttys[0-9]+$\")\n  (regex #\"^/dev/fd/\"))\n");
    p
}

/// A command that runs `program` with `args` under `policy` through
/// `sandbox-exec`.
#[cfg(target_os = "macos")]
#[must_use]
pub fn seatbelt_command(
    policy: &Policy,
    program: &std::ffi::OsStr,
    args: &[std::ffi::OsString],
) -> std::process::Command {
    let mut cmd = std::process::Command::new(SANDBOX_EXEC);
    cmd.arg("-p")
        .arg(seatbelt_profile(policy))
        .arg(program)
        .args(args);
    cmd
}

#[cfg(test)]
mod tests {
    #![allow(clippy::unwrap_used)]
    use super::*;

    #[test]
    fn policies_are_canonical_and_absolute() {
        let dir = tempfile::tempdir().unwrap();
        let p = Policy::new([dir.path(), dir.path()]).unwrap();
        assert_eq!(p.writable(), [dir.path().canonicalize().unwrap()]);
        assert!(matches!(
            Policy::new(["relative"]),
            Err(SandboxError::Relative { .. })
        ));
        assert!(matches!(
            Policy::new([dir.path().join("missing")]),
            Err(SandboxError::Path { .. })
        ));
    }

    #[test]
    fn seatbelt_profiles_escape_paths() {
        let dir = tempfile::tempdir().unwrap();
        let odd = dir.path().join("a \"b\\c");
        std::fs::create_dir(&odd).unwrap();
        let profile = seatbelt_profile(&Policy::new([&odd]).unwrap());
        assert!(profile.starts_with("(version 1)\n(allow default)\n(deny file-write*)\n"));
        assert!(profile.contains(r#"a \"b\\c")"#), "{profile}");
        assert!(profile.contains("(subpath "));
    }

    #[test]
    fn device_files_are_absolute() {
        assert!(DEVICE_FILES.iter().all(|d| d.starts_with("/dev/")));
    }
}
